import os
import re

_BACKUP = re.compile(r"backup-([0-9]+)\.tar")


def latest_backup(directory):
    """Name of the newest backup-N.tar in directory, or None."""
    names = [n for n in os.listdir(directory) if _BACKUP.fullmatch(n)]
    if not names:
        return None
    return max(names, key=lambda n: int(_BACKUP.fullmatch(n).group(1)))

